type LN = { n: string; g: string; b: string; c1n: string; c1e: string; c1m: string; c2n: string; c2e: string; c2m: string; mk: string; mc: string; mt: string; ex: string; fq: string; sc: string; dur: number };
type UN = { name: string; goal: string; pk: string[]; ek: string[]; kc: string[]; ls: LN[]; labTitle: string; labScenario: string; labCriterion: string; lq: Array<{ kind: "diagnostic"|"decision"|"application"|"analysis"|"connection"; p: string; r: string; o: string; pts: number }>; eq: Array<{ p: string; ch: string[]; ci: number; ex: string; d: 1|2|3 }> };
type ST = { name: string; goal: string; bf: "remember"|"understand"|"apply"|"analyze"|"evaluate"|"create"; sq: Array<{ p: string; ch: string[]; ci: number; ex: string; d: 1|2|3 }>; us: UN[] };
type LV = { name: string; goal: string; bf: "remember"|"understand"|"apply"|"analyze"|"evaluate"|"create"; lq: Array<{ p: string; ch: string[]; ci: number; ex: string; d: 1|2|3 }>; sts: ST[] };

function lesson(
  n: string, g: string, b: string,
  c1n: string, c1e: string, c1m: string,
  c2n: string, c2e: string, c2m: string,
  mk: string, mc: string, mt: string,
  ex: string, fq: string, sc: string, dur = 25
): LN {
  return { n, g, b, c1n, c1e, c1m, c2n, c2e, c2m, mk, mc, mt, ex, fq, sc, dur };
}

function mcq(p: string, ch: string[], ci: number, ex: string, d: 1|2|3 = 2): { p: string; ch: string[]; ci: number; ex: string; d: 1|2|3 } {
  return { p, ch, ci, ex, d };
}

function labQ(kind: "diagnostic"|"decision"|"application"|"analysis"|"connection", p: string, r: string, o: string, pts: number) {
  return { kind, p, r, o, pts };
}

