function buildLesson(l: LN, li: number, uc: string, prev: string|null, next: string|null) {
  return {
    lesson_index: li,
    name: l.n,
    goal: l.g,
    bridge_sentence: l.b,
    prerequisite_lessons: prev ? [prev] : [],
    enables_lessons: next ? [next] : [],
    concepts: [
      { name: l.c1n, explanation: l.c1e, mastery_criterion: l.c1m, weight: 2 },
      { name: l.c2n, explanation: l.c2e, mastery_criterion: l.c2m, weight: 2 },
    ],
    common_mistakes: [{ mistake: l.mk, correction: l.mc, treatment: l.mt, severity: "major" as const }],
    yemeni_examples: [l.ex],
    final_check_question: l.fq,
    session_complete_criterion: l.sc,
    expected_duration_minutes: l.dur,
  };
}

function buildLab(u: UN, uc: string) {
  return {
    lab_index: 1,
    title: u.labTitle,
    scenario: u.labScenario,
    completion_criterion: u.labCriterion,
    questions: u.lq.map(q => ({ kind: q.kind, prompt: q.p, rubric: q.r, solution_outline: q.o, points: q.pts })),
  };
}

function buildUnit(u: UN, ui: number, sc: string) {
  const uc = `${sc}.${ui}`;
  const lessons = u.ls.map((l, idx) => {
    const ln = idx + 1;
    const prev = idx > 0 ? `${uc}.${ln - 1}` : null;
    const next = idx < u.ls.length - 1 ? `${uc}.${ln + 1}` : null;
    return buildLesson(l, ln, uc, prev, next);
  });
  return {
    unit_index: ui,
    name: u.name,
    goal: u.goal,
    prerequisite_units: u.pk,
    enables_units: u.ek,
    key_concepts: u.kc,
    labs: [buildLab(u, uc)],
    lessons,
    exam: { pass_threshold_percent: 70, time_limit_minutes: 20 },
  };
}

function buildStage(st: ST, si: number, li: number) {
  const sc = `${li}.${si}`;
  return {
    stage_index: si,
    name: st.name,
    goal: st.goal,
    bloom_focus: st.bf,
    units: st.us.map((u, ui) => buildUnit(u, ui + 1, sc)),
    exam: { pass_threshold_percent: 70, time_limit_minutes: 40 },
  };
}

function buildLevel(lv: LV, li: number) {
  return {
    level_index: li,
    name: lv.name,
    goal: lv.goal,
    bloom_focus: lv.bf,
    stages: lv.sts.map((st, si) => buildStage(st, si + 1, li)),
    exam: { pass_threshold_percent: 70, time_limit_minutes: 90 },
  };
}

function buildExamBanks(levels: LV[]) {
  const unitBanks: Record<string, unknown> = {};
  const stageBanks: Record<string, unknown> = {};
  const levelBanks: Record<string, unknown> = {};
  levels.forEach((lv, li) => {
    const lIdx = li + 1;
    levelBanks[String(lIdx)] = { variants: [lv.lq.map(q => ({ kind: "mcq", prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d }))] };
    lv.sts.forEach((st, si) => {
      const sc = `${lIdx}.${si + 1}`;
      stageBanks[sc] = { variants: [st.sq.map(q => ({ kind: "mcq", prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d }))] };
      st.us.forEach((u, ui) => {
        const uc = `${sc}.${ui + 1}`;
        unitBanks[uc] = { variants: [u.eq.map(q => ({ kind: "mcq", prompt: q.p, choices: q.ch, correct_index: q.ci, explanation: q.ex, difficulty: q.d }))] };
      });
    });
  });
  return { unit_banks: unitBanks, stage_banks: stageBanks, level_banks: levelBanks };
}

