async function main() {
  const builtLevels = LEVELS.map((lv, li) => buildLevel(lv, li + 1));
  const examBanks = buildExamBanks(LEVELS);

  const doc = {
    schema_version: "v4.1",
    specialty: {
      slug: SLUG,
      name: "إدارة الأعمال",
      icon: "💼",
      description: "مسار متكامل من أساسيات الأعمال حتى القيادة الاستراتيجية — يُخرج مديراً قادراً على تحليل البيئة وصياغة الاستراتيجيات وقيادة الفرق في السياقَين العربي والدولي",
      target_persona: "طالب جامعي أو خريج يطمح لبناء مسيرة إدارية في شركات أو مشاريعه الخاصة، يفهم العربية ويتطلع للاحتراف بالمعايير الدولية مع مراعاة خصوصية السياق العربي",
      teacher_tone: "مرشد ذو خبرة عملية — يقدم النظرية مقرونة بحالات دراسية حقيقية من الواقع العربي والدولي، يشجع التفكير النقدي لا الحفظ",
      allowed_viz_templates: ["flowchart", "comparison_table", "architecture_diagram", "timeline", "tree_diagram", "matrix_diagram"],
    },
    levels: builtLevels,
    exam_banks: examBanks,
    placement_test_questions: PLACEMENT_QUESTIONS,
    publish_notes: "ملف v4.1 كامل — المستوى الأول مكتمل بتفصيل عالٍ للمراحل 1-4، المستويان 2 و3 هيكل مكتمل"
  };

  const json = JSON.stringify(doc, null, 2);
  fs.writeFileSync(OUT, json, "utf-8");
  console.log(`\nكتبت الملف: ${OUT}`);
  console.log(`الحجم: ${(json.length / 1024).toFixed(0)} KB`);

  const s = builtLevels.reduce((acc, lv) => {
    lv.stages.forEach((st: any) => {
      acc.stages++;
      st.units.forEach((u: any) => {
        acc.units++;
        acc.lessons += u.lessons.length;
        acc.labs += u.labs.length;
      });
    });
    return acc;
  }, { stages: 0, units: 0, lessons: 0, labs: 0 });
  console.log(`المستويات: ${builtLevels.length} | المراحل: ${s.stages} | الوحدات: ${s.units} | الدروس: ${s.lessons} | المعامل: ${s.labs}`);
}

main().catch(e => { console.error(e); process.exit(1); });
